public class Solution {
    public double Average(int[] salary) {
        int min = int.MaxValue;
        int max = int.MinValue;
        long sum = 0;
        foreach (int s in salary) {
            if (s < min) min = s;
            if (s > max) max = s;
            sum += s;
        }
        return (sum - min - max) / (double)(salary.Length - 2);
    }
}
```

