public class Solution {
    public string AbbreviateProduct(int left, int right) {
        BigInteger prod = 1;
        for (int i = left; i <= right; i++) {
            prod *= i;
        }
        int zeros = 0;
        while (prod %  10 == 0) {
            prod /= 10;
            zeros++;
        }
        string s = prod.ToString();
        int d = s.Length;
        if (d <= 10) {
            return s + "e" + zeros;
        }
        string pre = s.Substring(0,  5);
        string suf = s.Substring(s.Length - 5);
        return pre + "..." + suf + "e" + zeros;
    }
}
