public class Solution {
    public bool KLengthApart(int[] nums, int k) {
        int last = -1;
        for (int i = 0; i < nums.Length; i++) {
            if (nums[i] == 1) {
                if (last != -1 && i - last < k + 1) return false;
                last = i;
            }
        }
        return true;
    }
}
