```csharp
public class Solution {
    public int NumFactoredBinaryTrees(int[] arr) {
        Array.Sort(arr);
        var dp = new Dictionary<int, long>();
        foreach (int x in arr) dp[x] = 1;
        const long MOD = 1000000007;
        int n = arr.Length;
        for (int i = 0; i < n; i++) {
            long extra = 0;
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int right = arr[i] / arr[j];
                    if (dp.ContainsKey(right)) {
                        extra = (extra + dp[arr[j]] * dp[right]) % MOD;
                    }
                }
            }
            dp[arr[i]] = (dp[arr[i]] + extra) % MOD;
        }
        long ans = 0;
        foreach (long v in dp.Values) ans = (ans + v) % MOD;
        return (int)ans;
    }
}
```

