public class MKAverage {
    private const int MAXV = 100000;
    private readonly int m;
    private readonly int k;
    private readonly Queue<int> window;
    private readonly Fenwick cnt;
    private readonly Fenwick sum;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        window = new Queue<int>();
        cnt = new Fenwick(MAXV);
        sum = new Fenwick(MAXV);
    }

    public void AddElement(int num) {
        window.Enqueue(num);
        cnt.Update(num, 1);
        sum.Update(num, num);
        if (window.Count > m) {
            int old = window.Dequeue();
            cnt.Update(old, -1);
            sum.Update(old, -old);
        }
    }

    public int CalculateMKAverage() {
        if (window.Count < m) return -1;
        long midSum = GetSumOfSmallest(m - k) - GetSumOfSmallest(k);
        return (int)(midSum / (m - 2 * k));
    }

    private long GetSumOfSmallest(int x) {
        if (x <= 0) return 0;
        int lo = 1, hi = MAXV;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (cnt.Query(mid) >= x) hi = mid;
            else lo = mid + 1;
        }
        long cntBefore = cnt.Query(lo - 1);
        long sumBefore = sum.Query(lo - 1);
        return sumBefore + (x - cntBefore) * lo;
    }

    private class Fenwick {
        private readonly long[] tree;
        private readonly int n;

        public Fenwick(int n) {
            this.n = n;
            tree = new long[n + 1];
        }

        public void Update(int i, long delta) {
            for (; i <= n; i += i & -i) tree[i] += delta;
        }

        public long Query(int i) {
            long s = 0;
            for (; i > 0; i -= i & -i) s += tree[i];
            return s;
        }
    }
}
```

