public class Solution {
    public bool CanCross(int[] stones) {
        if (stones.Length == 1) return true;
        if (stones[1] != 1) return false;

        var stoneSet = new HashSet<int>(stones);
        var reached = new Dictionary<int, HashSet<int>>();
        foreach (var s in stones) {
            reached[s] = new HashSet<int>();
        }
        reached[0].Add(0);

        foreach (var stone in stones) {
            foreach (var k in reached[stone]) {
                for (int jump = k -  1; jump <= k + 1; jump++) {
                    if (jump > 0) {
                        long next = (long)stone + jump;
                        if (next <= int.MaxValue && stoneSet.Contains((int)next)) {
                            reached[(int)next].Add(jump);
                        }
 if (next == stones[stones.Length - 1]) return true;
                    }
                }
            }
        }
        return reached[stones[stones.Length - 1]].Count > 0;
    }
}
```     The solution uses a dictionary to track reachable jump distances at each stone position. It starts with the frog at position 0 having made a jump of 0 (allowing the first jump of 1). For each stone, it tries the three possible next jump sizes (k-1, k, k+1) and checks if the landing position is a valid stone. If the frog reaches the last stone, it returns true immediately. The approach is O(n²) which is acceptable for n ≤ 2000. I used a HashSet for quick stone lookups and ensured jump calculations use long to prevent overflow.

