public class Solution {
    public int MaxPoints(int[][] points) {
        int n = points.Length;
        if (n <= 2) return n;
        int ans = 1;
        int Gcd(int a, int b) {
            while (b != 0) {
                int t = b;
                b = a % b;
                a = t;
            }
            return a;
        }
        for (int i = 0; i < n; i++) {
            var dict = new Dictionary<(int, int), int>();
            int local = 0;
            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = Gcd(Math.Abs(dx), Math.Abs(dy));
                dx /= g;
                dy /= g;
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                var key = (dx, dy);
                if (!dict.ContainsKey(key)) dict[key] = 0;
                dict[key]++;
                if (dict[key] > local) local = dict[key];
            }
            ans = Math.Max(ans, local + 1);
        }
        return ans;
    }
}
