public class Solution {
    public int MaxScore(int[] nums) {
        int m = nums.Length;
        int[] memo = new int[1 << m];
        Array.Fill(memo, -1);
        int Gcd(int a, int b) {
            while (b != 0) {
                int t = b;
                b = a % b;
                a = t;
            }
            return a;
        }
        int Dfs(int mask) {
            if (memo[mask] != -1) return memo[mask];
            int used = 0;
            for (int i = 0; i < m; i++) if ((mask & (1 << i)) != 0) used++;
            if (used == m) {
                memo[mask] = 0;
                return 0;
            }
            int op = used / 2 + 1;
            int maxScore = 0;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) continue;
                for (int j = i + 1; j < m; j++) {
                    if ((mask & (1 << j)) != 0) continue;
                    int g = Gcd(nums[i], nums[j]);
                    int newMask = mask | (1 << i) | (1 << j);
                    maxScore = Math.Max(maxScore, op * g + Dfs(newMask));
                }
            }
            memo[mask] = maxScore;
            return maxScore;
        }
        return Dfs(0);
    }
}
