public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int n = nums.Length;
        int maxMask = 1;
        for (int i = 0; i < numSlots; i++) maxMask *= 3;
        int[][] dp = new int[n + 1][];
        for (int i = 0; i <= n; i++) {
            dp[i] = new int[maxMask];
            Array.Fill(dp[i], -1);
        }
        dp[0][0] = 0;
        int[] p3 = new int[numSlots];
        p3[0] = 1;
        for (int i = 1; i < numSlots; i++) p3[i] = p3[i - 1] * 3;
        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < maxMask; mask++) {
                if (dp[i][mask] < 0) continue;
                for (int s = 0; s < numSlots; s++) {
                    int occ = (mask / p3[s]) % 3;
                    if (occ < 2) {
                        int nmask = mask + p3[s];
                        int val = dp[i][mask] + (nums[i] & (s + 1));
                        if (val > dp[i + 1][nmask]) dp[i + 1][nmask] = val;
                    }
                }
            }
        }
        int ans = 0;
        for (int mask = 0; mask < maxMask; mask++) {
            if (dp[n][mask] > ans) ans = dp[n][mask];
        }
        return ans;
    }
}
