public class Solution {
    public bool IsCousins(TreeNode root, int x, int y) {
        TreeNode px = null, py = null;
        int dx = -1, dy = -1;
        Find(root, null, 0, x, ref px, ref dx);
        Find(root, null, 0, y, ref py, ref dy);
        return dx == dy && px != py;
    }

    private void Find(TreeNode node, TreeNode parent, int depth, int target, ref TreeNode foundParent, ref int foundDepth) {
        if (node == null) return;
        if (node.val == target) {
            foundParent = parent;
            foundDepth = depth;
            return;
        }
        Find(node.left, node, depth + 1, target, ref foundParent, ref foundDepth);
        Find(node.right, node, depth + 1, target, ref foundParent, ref foundDepth);
    }
}
