    public IList<int> EventualSafeNodes(int[][] graph) {
        int n = graph.Length;
        var reverse = new List<int>[n];
        var outdegree = new int[n];
        for (int i = 0; i < n; i++) {
            reverse[i] = new List<int>();
            outdegree[i] = graph[i].Length;
        }
        for (int u = 0; u < n; u++) {
            foreach (int v in graph[u]) {
                reverse[v].Add(u);
            }
        }
        var q = new Queue<int>();
        for (int i = 0; i < n; i++) {
            if (outdegree[i] == 0) {
                q.Enqueue(i);
            }
        }
        var safe = new List<int>();
        while (q.Count > 0) {
            int u = q.Dequeue();
            safe.Add(u);
            foreach (int v in reverse[u]) {
                if (--outdegree[v] == 0) {
                    q.Enqueue(v);
                }
            }
        }
        safe.Sort();
        return safe;
    }
}
