    public int LargestMagicSquare(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;
        int maxK = Math.Min(m, n);
        int[][] rowSum = new int[m][];
        for (int i = 0; i < m; i++) {
            rowSum[i] = new int[n + 1];
            for (int j = 0; j < n; j++) {
                rowSum[i][j + 1] = rowSum[i][j] + grid[i][j];
            }
        }
        int[][] colSum = new int[n][];
        for (int j = 0; j < n; j++) {
            colSum[j] = new int[m + 1];
            for (int i = 0; i < m; i++) {
                colSum[j][i + 1] = colSum[j][i] + grid[i][j];
            }
        }
        for (int k = maxK; k >= 1; k--) {
            for (int i = 0; i <= m - k; i++) {
                for (int j = 0; j <= n - k; j++) {
                    int target = rowSum[i][j + k] - rowSum[i][j];
                    bool ok = true;
                    for (int r = i; r < i + k; r++) {
                        if (rowSum[r][j + k] - rowSum[r][j] != target) {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;
                    for (int c = j; c < j + k; c++) {
                        if (colSum[c][i + k] - colSum[c][i] != target) {
                            ok = false;
                            break;
                        }
