public class Solution {
    public int MaxStudents(char[][] seats) {
        int m = seats.Length, n = seats[0].Length;
        int[] avail = new int[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') avail[i] |= (1 << j);
            }
        }
        int N = 1 << n;
        int[][] dp = new int[m][];
        for (int i = 0; i < m; i++) {
            dp[i] = new int[N];
            Array.Fill(dp[i], -1);
        }
        int BitCount(int x) {
            int c = 0;
            while (x > 0) { c += x & 1; x >>= 1; }
            return c;
        }
        for (int mask = 0; mask < N; mask++) {
            if ((mask & avail[0]) == mask && (mask & (mask << 1)) == 0) {
                dp[0][mask] = BitCount(mask);
            }
        }
        for (int i = 1; i < m; i++) {
            for (int mask = 0; mask < N; mask++) {
                if ((mask & avail[i]) != mask || (mask & (mask << 1)) != 0) continue;
                int bits = BitCount(mask);
                for (int pmask = 0; pmask < N; pmask++) {
                    if (dp[i - 1][pmask] == -1) continue;
                    if ((mask & (pmask << 1)) == 0 && (mask & (pmask >> 1)) == 0) {
                        dp[i][mask] = Math.Max(dp[i][mask], dp[i - 1][pmask] + bits);
                    }
                }
            }
        }
        int ans = 0;
        for (int mask = 0; mask < N; mask++) ans = Math.Max(ans, dp[m - 1][mask]);
        return ans;
    }
}
