```csharp
public class Solution {
    public IList<string> RemoveInvalidParentheses(string s) {
        var result = new List<string>();
        var visited = new HashSet<string>();
        var queue = new Queue<string>();
        queue.Enqueue(s);
        visited.Add(s);

        bool IsValid(string str) {
            int count = 0;
            foreach (char c in str) {
                if (c == '(') count++;
                else if (c == ')') {
                    if (count == 0) return false;
                    count--;
                }
            }
            return count == 0;
        }

        while (queue.Count > 0) {
            int size = queue.Count;
            var currents = new List<string>(size);
            for (int i = 0; i < size; i++) {
                currents.Add(queue.Dequeue());
            }

            bool foundThisLevel = false;
            foreach (var curr in currents) {
                if (IsValid(curr)) {
                    result.Add(curr);
                    foundThisLevel = true;
                }
            }
            if (foundThisLevel) break;

            foreach (var curr in currents) {
                for (int j = 0; j < curr.Length; j++) {
                    if (curr[j] != '(' && curr[j] != ')') continue;
                    string next = curr.Substring(0, j) + curr.Substring(j + 1);
                    if (visited.Add(next)) {
                        queue.Enqueue(next);
                    }
                }
            }
        }
        return result;
    }
}
