        for (int i = start; i <= 10000000; i++) {
            if (IsBalanced(i)) return i;
        }
        return -1;
    }

 private bool IsBalanced(int num) {
        if (num == 0) return false;
        int[] count = new int[10];
        int temp = num;
        while (temp > 0) {
            int d = temp % 10;
            if (d == 0) return false;
 count[d]++;
            temp /= 10;
        }
        for (int d = 1; d <= 9; d++) {
            if (count[d] != d) return false;
        }
        return true;
    }
}
