        return Count(nums1, nums2) + Count(nums2, nums1);
    }

    private int Count(int[] a, int[] b) {
        var sq = new Dictionary<long, int>();
        foreach (int x in a) {
            long s = (long)x * x;
            if (!sq.ContainsKey(s)) sq[s] = 0;
            sq[s]++;
        }
        int n = b.Length;
        int res = 0;
        for (int j = 0; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                long p = (long)b[j] * b[k];
                if (sq.TryGetValue(p, out int c)) res += c;
            }
        }
        return res;
    }
}
