public class Solution {
    public int SplitArray(int[] nums, int k) {
        int maxVal = 0;
        long total = 0;
        foreach (int num in nums) {
            if (num > maxVal) maxVal = num;
            total += num;
        }
        int low = maxVal;
        int high = (int)total;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (CanSplit(nums, k, mid)) {
                high = mid;
            } else {
