public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int N = n * n * 4;
        int[] parent = new int[N];
        int[] rank = new int[N];
        int count = N;
        for (int i = 0; i < N; i++) parent[i] = i;

        int Find(int x) {
            if (parent[x] != x) parent[x] = Find(parent[x]);
            return parent[x];
        }

        void Union(int x, int y) {
            int px = Find(x), py = Find(y);
            if (px == py) return;
            if (rank[px] < rank[py]) parent[px] = py;
            else {
                parent[py] = px;
                if (rank[px] == rank[py]) rank[px]++;
            }
            count--;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int root = (i * n + j) * 4;
                char c = grid[i][j];
                if (c == '/') {
                    Union(root + 0, root + 3);
                    Union(root + 1, root + 2);
                } else if (c == '\\') {
                    Union(root + 0, root + 1);
                    Union(root + 2, root + 3);
                } else {
                    Union(root + 0, root + 1);
                    Union(root + 1, root + 2);
                    Union(root + 2, root + 3);
                }
                if (j + 1 < n) {
                    int right = (i * n + j + 1) * 4;
                    Union(root + 1, right + 3);
                }
                if (i + 1 < n) {
                    int below = ((i + 1) * n + j) * 4;
                    Union(root + 2, below + 0);
                }
            }
        }
        return count;
    }
}
