public class Solution {
    public int SumOddLengthSubarrays(int[] arr) {
        int n = arr.Length;
        int sum = 0;
        for (int i = 0; i < n; i++) {
            int evenA = (i + 2) / 2;
            int oddA = (i + 1) / 2;
            int R = n - 1 - i;
            int evenB = (R + 2) / 2;
            int oddB = (R + 1) / 2;
            int count = evenA * evenB + oddA * oddB;
            sum += arr[i] * count;
        }
        return sum;
    }
}
