public class Solution {
    public int[] GetCoprimes(int[] nums, int[][] edges) {
        int n = nums.Length;
        var graph = new List<int>[n];
        for (int i = 0; i < n; i++) graph[i] = new List<int>();
        foreach (var e in edges) {
            graph[e[0]].Add(e[1]);
            graph[e[1]].Add(e[0]);
        }

        var coprimes = new List<int>[51];
        for (int i = 1; i <= 50; i++) {
            coprimes[i] = new List<int>();
            for (int j = 1; j <= 50; j++) {
                if (Gcd(i, j) == 1) coprimes[i].Add(j);
            }
        }

        var last = new List<(int node, int depth)>[51];
        for (int i = 1; i <= 50; i++) last[i] = new List<(int, int)>();

        int[] ans = new int[n];
        Array.Fill(ans, -1);

        var stack = new Stack<(int u, int parent, int depth, bool enter)>();
        stack.Push((0, -1, 0, true));

        while (stack.Count > 0) {
            var (u, parent, depth, enter) = stack.Pop();
            int val = nums[u];
            if (enter) {
                int bestD = -1, bestN = -1;
                foreach (int v in coprimes[val]) {
                    if (last[v].Count > 0) {
                        var (nd, dep) = last[v][last[v].Count - 1];
                        if (dep > bestD) {
                            bestD = dep;
                            bestN = nd;
                        }
                    }
                }
                if (bestN != -1) ans[u] = bestN;
                last[val].Add((u, depth));
                stack.Push((u, parent, depth, false));
                foreach (int nei in graph[u]) {
                    if (nei != parent) {
                        stack.Push((nei, u, depth + 1, true));
                    }
                }
            } else {
                last[val].RemoveAt(last[val].Count - 1);
            }
        }
        return ans;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
