public class Solution {
    public int[] KWeakestRows(int[][] mat, int k) {
        int m = mat.Length;
        var rows = new (int soldiers, int index)[m];
        for (int i = 0; i < m; i++) {
            int soldiers = 0;
            foreach (int cell in mat[i]) {
                if (cell == 1) soldiers++;
                else break;
