            rows[i] = (soldiers, i);
        }
        Array.Sort(rows, (a, b) => a.soldiers != b.soldiers ? a.soldiers.CompareTo(b.soldiers) : a.index.CompareTo(b.index));
        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = rows[i].index;
        }
        return result;
    }
}
